<?php
namespace App\Services;
use App\Models\{AdvertisingInvoice,AdvertisingPayment}; use Illuminate\Support\Str; use Stripe\Checkout\Session; use Stripe\Stripe;
class AdvertisingStripeCheckoutService {public function __construct(){Stripe::setApiKey(config('stripe.secret'));} public function create(AdvertisingInvoice $invoice): Session {$invoice->load('advertiser'); abort_if($invoice->balance_cents<1,422,'Invoice has no outstanding balance.'); abort_if($invoice->status==='void',422,'Void invoices cannot be paid.'); $payment=AdvertisingPayment::create(['uuid'=>(string)Str::uuid(),'advertising_invoice_id'=>$invoice->id,'type'=>'payment','status'=>'pending','provider'=>'stripe','amount_cents'=>$invoice->balance_cents,'currency'=>$invoice->currency]); $session=Session::create(['mode'=>'payment','customer_email'=>$invoice->advertiser->billing_email,'line_items'=>[['quantity'=>1,'price_data'=>['currency'=>strtolower($invoice->currency),'unit_amount'=>$invoice->balance_cents,'product_data'=>['name'=>'Advertising Invoice '.$invoice->invoice_number]]]],'success_url'=>url('/admin/advertising-invoices/'.$invoice->id.'?payment=success'),'cancel_url'=>url('/admin/advertising-invoices/'.$invoice->id.'?payment=canceled'),'metadata'=>['billing_type'=>'advertising_invoice','advertising_invoice_id'=>(string)$invoice->id,'advertising_payment_id'=>(string)$payment->id]],['idempotency_key'=>'advertising-invoice-'.$invoice->id.'-'.$payment->id]); $payment->update(['stripe_checkout_session_id'=>$session->id]); return $session;}}
